CREATE TABLE IF NOT EXISTS token_families (
  id TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id),
  created_at INTEGER NOT NULL,
  revoked_at INTEGER NULL
);

const revokeFamily = (familyId: string): void => {
  db.prepare(
    "UPDATE token_families SET revoked_at = ? WHERE id = ?"
  ).run(Date.now(), familyId);
  db.prepare(
    "UPDATE refresh_tokens SET revoked_at = ? WHERE family_id = ? AND revoked_at IS NULL"
  ).run(Date.now(), familyId);
};

const isFamilyRevoked = (familyId: string): boolean => {
  const row = db
    .prepare<[string], { revoked_at: number | null }>(
      "SELECT revoked_at FROM token_families WHERE id = ?"
    )
    .get(familyId);
  return row == null || row.revoked_at != null;
};

const rotate = async (oldToken: string) => {
  const row = repo.findByHash(sha256(oldToken));
  if (!row || row.expires_at < Date.now() || repo.isFamilyRevoked(row.family_id)) {
    throw new InvalidToken();
  }
  if (row.revoked_at) {
    repo.revokeFamily(row.family_id);
    throw new TokenReuseDetected();
  }
  repo.revoke(row.id);
  const user = await users.findById(row.user_id);
  const access = await signAccessToken(user, row.family_id);
  const refresh = newRefreshToken();
  repo.insert({
    familyId: row.family_id,
    userId: user.id,
    hash: sha256(refresh),
    expiresAt: Date.now() + REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
  });
  return { access, refresh };
};

return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  const token = auth.slice(7);
  try {
    const payload = await verifyAccessToken(token);
    const fid = payload["fid"] as string | undefined;
    if (!fid || repo.isFamilyRevoked(fid)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    (req as Request & { userId: number }).userId = Number(payload.sub);
    next();
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
};

export async function verifyAccessToken(token: string): Promise<JWTPayload> {
  const { payload } = await jwtVerify(token, secretBytes, {
    clockTolerance: 5,
  });
  return payload;
}

it("expired access token is rejected with 401", async () => {
  const { app } = setup();
  const loginRes = await request(app)
    .post("/auth/login")
    .send({ email: "alice@shoply.test", password: "demo1234" });
  expect(loginRes.status).toBe(200);
  const { accessToken } = loginRes.body as { accessToken: string };

  vi.useFakeTimers();
  vi.setSystemTime(Date.now() + 16 * 60 * 1000);

  const res = await request(app)
    .get("/me")
    .set("Authorization", `Bearer ${accessToken}`);
  expect(res.status).toBe(401);
});

